INSERT INTO creatures (slug, name, category, system, playable, alignment, attributes, hp, sdc, mdc, ppe, isp, pools_note, ar, horror_factor, combat, bonuses_note, skills_note, natural_abilities, magic, psionics, size, weight, life_span, habitat, allies, enemies, occ_note, description, source_book) VALUES
('harvester', 'Harvester (Soul Harvester)', 'humanoid', 'rifts', 0, 'Miscreant or diabolic', '{}', NULL, NULL, NULL, NULL, NULL, 'Printed as an O.C.C., so no attribute dice are given: attributes are those of the character''s race (60% of Harvesters on Rifts Earth are human). Attribute requirements: I.Q. 12, M.E. 10 and P.E. 12 or higher. P.P.E. is a base of P.E. x2 (not stored: the row rolls no P.E.) and never grows by level; each harvested soul adds the P.P.E. the victim had in life. Each captured soul also adds 2D6+10 Hit Points and +2 P.S. (P.S. over 30 becomes supernatural); all of it is lost if the soul is released or freed. Holds at most two souls per level of experience. No Hit Points, S.D.C. or Horror Factor are printed.', NULL, NULL, '{"initiative":2,"pull":2}', 'O.C.C. bonuses: +2 to save vs Horror Factor at levels 1, 2, 4, 6, 8 and 12; +1 to save vs magic and +1 to spell strength at levels 3, 7, 10 and 13; +3 to save vs possession, +2 on initiative, +2 to pull punch, +1 to save vs poison and disease. For 15-20 minutes after a harvest it is euphoric and all attacks, bonuses and skills are halved. Takes double damage from psionic energy attacks (Pyrokinesis, Electrokinesis, Psi-Sword, Mind Bolt and the like), and psychics are +2 to save vs its magic. Must save vs insanity (16 or higher) every three levels, at a cumulative -1 each time. No attacks per melee are printed (Hand to Hand: Basic).', 'O.C.C. skills: native language 98%, one additional language +15%, literate in native language +15%, Lore: Demon +10%, Lore: Magic +10%, Lore: D-Bee +5%, Biology +10%, Preserve Foods +20%, Skin & Preserve Hides +10%, Wilderness Survival +5%, one Pilot skill of choice +10%, Dance +10%, Sing +10%, W.P. Knife, one W.P. of choice, Hand to Hand: Basic (Expert for one O.C.C. Related pick, Assassin for two). Six O.C.C. Related skills (one must be medical; two more at levels 3, 5 and 9; no Electrical, Mechanical, Military or extra Wilderness) and four Secondary skills. Each harvested victim who knew a skill the Harvester also has adds a cumulative +2% to it. Sense ley line 20% +4% per level (range 10 miles/16 km per level); sense ley line nexus 30% +5% per level.', 'Senses ley lines and nexus points and sees magic energy (over 20 P.P.E., line of sight about 1000 ft/305 m) at no P.P.E. cost. Soul Searching: reads a being''s general level, alignment, magic or psychic ability, possessing entities, whether it has a soul, how high its P.P.E. is and its strongest desire. Communes with captive souls, entities, astral beings and spirits. Harvesting of Souls: a forbidden ritual in a permanent chamber whose circle is charged with 65 P.P.E.; the victim is stabbed through both eyes and the soul bound to the Harvester over about half an hour for 35 P.P.E. (it escapes if the rite runs past 40 minutes). Learns the names and relationships of people its victims knew. Commands one Soulless Xombie per level. Psychics cannot be harvested, and each exorcism frees one captive soul; killing the Harvester frees them all.', 'At level one: the Necromantic spells Object Read the Dead, Recognize Undead, Consume Power & Knowledge, Command Ghouls, Animate and Control Dead and Turn Dead, plus 1D4 spells each from spell levels one and two. 1D4 new spells per later level, chosen from levels up to its own. Harvesting a spell caster lets it take 1D4+6 of the victim''s spells (lost if the soul is freed). Most of its spell knowledge is supplied by Nxla.', 'None; a Harvester cannot be a psychic of any kind.', NULL, NULL, NULL, 'North America only: about 2300 in Soulharvest in the Magic Zone, 400-500 elsewhere in the Magic Zone and a few dozen beyond it', 'Nxla, the Harvester of Souls, whose minions they are; the Soulless Xombies they command', 'Psychics, especially Mind Melters and the natural destroyers of the supernatural (Psi-Warriors, Psi-Nullifiers, Nega-Psychics, Psi-Stalkers, Darkhounds, Psi-Hounds); above all the people of Psyscape', 'Printed as the Harvester O.C.C., but the book rules it out as a player character (NPC villain only). Also called Soul Eaters and Minions of Nxla. Any race may take it; must be miscreant or diabolic. Equipment: ceremonial robe, stakes and mallet, survival gear, light M.D.C. armor, a high-tech pistol with 1D4 E-Clips, a simple Techno-Wizard weapon and two silver-plated knives; one vehicle or riding animal. Will never take cybernetics.', 'A forbidden school of necromancy handed to mortal fanatics by the alien intelligence Nxla. Harvesters ritually murder victims to imprison their souls inside themselves, feeding their magic and health on the captured life force. Their cult aims to muster 6,601 members and over 5000 Soulless Xombies, enough to bring Nxla bodily to Earth.', 'Rifts World Book 12: Psyscape p.17-20'),
('soulless-xombie', 'Soulless Xombie', 'monster', 'rifts', 0, 'Effectively diabolic; a puppet of Nxla', '{"IQ":"4","ME":"N/A","MA":"2","PS":"1D6+29","PP":"12","PE":"N/A","Spd":"1D6+10"}', NULL, NULL, '2D6x10+130', '1D4', NULL, 'P.B. is half that of the original person, so it is not stored. P.S. is supernatural. A Mega-Damage creature; may wear body armor, but only as decoration or disguise.', NULL, 13, '{"attacks":4,"initiative":1,"strike":4,"parry":1}', 'Impervious to Horror Factor. M.D. fire, energy weapons and magic that affects the body do full damage; psionic energy attacks and Millennium Tree, holy and rune weapons do double damage. Bonuses are in addition to attribute bonuses.', 'Track 50%, climb 70%/60%, prowl 50%.', 'Normal color vision and nightvision 300 ft (91 m; the book prints 183 m); leaps 10 ft (3 m) high and 20 ft (6 m) long; bio-regenerates 1D4x10 M.D.C. per melee round; impervious to poison, radiation, disease, mind control, possession, illusions, cold and heat. Obeys only Harvesters and Nxla; uncontrolled ones wander and attack intelligent beings on sight.', 'None', 'None', 'As the original person or creature', 'As the original person or creature', 'Immortal until destroyed or exorcised', 'Wherever Harvesters are; common only in the Magic Zone around Soulharvest and the Kingdom of Dunscon', 'Commanded by Harvesters and Nxla; never attacks Harvesters, Necromancers, Death Worshippers or Nxla''s minions unless attacked first', 'Every intelligent being that still has its soul', 'Not available as a player character (NPC villain and monster only). The stats apply whatever the original race.', 'The living body of someone whose soul was torn out by a fragment of Nxla during a Harvester-opened portal, now animated by a cold shard of the alien intelligence. Mindless and will-less, it serves as a slave, guard and soldier. The body can be restored if captured alive and put through a counter-ritual; killing it sends the fragment home and strands the soul inside Nxla.', 'Rifts World Book 12: Psyscape p.21-22'),
('blood-hawk', 'Blood Hawk', 'monster', 'rifts', 0, 'Considered a diabolic animal predator', '{"IQ":"1D4+2","ME":"3D6+8","MA":"1D6","PS":"1D6+15","PP":"1D6+13","PE":"2D6+10","PB":"2D6","Spd":"2D4x10+35"}', NULL, NULL, 'PE+1D4x10', '3D6', 'MEx2', 'Spd 2D4x10+35 is flying (average about 70, some 50 mph); 1D6 on the ground; it can dive at twice its flying speed (counts as two melee actions). Maximum altitude about three miles (16,000 ft). I.Q. is animal; M.A. 1D6 applies except among its own kind. Supernatural attributes. Flock sizes: small 1D4+3, medium 2D4+5, large (rare) 20 or more.', NULL, 10, '{"attacks":4,"initiative":5,"strike":3,"automatic_dodge":2,"pull":3,"roll":2}', 'Horror Factor 15 for a flock of 5-14. The four attacks are physical attacks or uses of psionics. Cannot parry; its dodge is automatic and costs no melee attack. Critical strike on a natural 19-20. Impervious to disease; +4 to save vs poison, +2 vs Horror Factor. Needs a 12 or higher to save vs psionics and is -2 to save vs magic.', 'Land Navigation (sense of direction) 90%, Track by sight 72%, Climb 40%/30%.', 'Flight; hawk-keen eyesight (spots a rabbit two miles away); supernatural strength and endurance; great speed and agility. Cannot be tamed, not even by Simvan or Psi-Druids.', 'None', 'Limited: Sense Magic, Detect Psionics and See Aura.', 'About 2 ft (0.6 m) tall; wingspan about 4-5 ft (1.2-1.5 m)', '15-20 lbs (6.8-9 kg)', '50 years', 'Temperate forests, plains and mountains of North America; common in the Western territories, Lone Star, Mexico and along the Rockies, uncommon where magic is strong (Magic Zone, Midwest, Ontario)', NULL, 'Psi-Stalkers, Psi-Hounds and other CS mutant animals, Darkhounds and Simvan (avoided in numbers, killed when alone); leaves psychics, mages, supernatural beings and M.D.C. creatures alone as too dangerous', NULL, 'Also called the Demon Hawk or Demon Bird: a hawk-shaped predator with a leathery blood-red hide in place of feathers and glowing eyes, either alien or a Rifts-era mutation. Flocks scout their prey, then swarm vulnerable animals, children and small groups of people; they shun confined spaces and use their limited psionics to pick weak targets.', 'Rifts World Book 12: Psyscape p.90-92'),
('dark-behemoth', 'Dark Behemoth', 'monster', 'rifts', 0, 'Considered a diabolic animal predator', '{"IQ":"1D4+1","ME":"2D6+4","MA":"1D6","PS":"3D6+30","PP":"2D6+6","PE":"3D6+12","PB":"1D6","Spd":"3D6+46"}', NULL, NULL, '1D4x100+320', '2D6x10', NULL, 'Spd 3D6+46 is running (about 40 mph); doubles for bursts of 1D4+1 melee rounds as often as every 10 minutes; tunnels at Spd 2D6+10. I.Q. is animal. Supernatural attributes. Heals 3D6 M.D. per hour.', NULL, 15, '{"attacks":5,"initiative":5,"strike":4,"roll":2}', '+2 to save vs poison and magic; +6 to save vs Horror Factor (too dim to be afraid). From ambush it gets one bite against a single target before combat begins, and that victim cannot defend. Face tentacles are +4 to entangle.', 'Track by smell 77%; senses surface movement from underground 62%; Concealment (self) 88%; Climb 60%/10%.', 'Three tiny eyes, two large mouths, one per cheek and a cluster of 6-12 face tentacles (supernatural P.S. about 17) that snare prey and drag it to either mouth, so two victims can be held at once; the tentacles also lash like a whip. Nightvision 300 ft; exceptional hearing and smell; senses seismic vibration; tunnels; leaps 20 ft high and 40 ft long; supernatural strength and endurance; heals fast; slow metabolism, so it eats less than its size suggests.', 'None', 'None', '12-15 ft (3.6-4.6 m) tall; 25-40 ft (7.6-12.2 m) long', '2-6 tons', '180-200 years', 'Temperate forests; scattered across North America and comparatively uncommon', 'None as such', 'Preys on anything and everything', NULL, 'Also called the Demon Hound or Tank Dog: a van-sized, demonic dog-like brute that lies in shallow burrows and lunges out at anything passing, often hauling prey underground to finish it. A lazy, mostly solitary hunter that sleeps and suns itself between gorging, it will attack vehicles and power armor when hungry, and the Coalition has marked it for extermination.', 'Rifts World Book 12: Psyscape p.92-94'),
('dragon-ape', 'Dragon-Ape', 'monster', 'rifts', 0, 'Typically miscreant (40%), diabolic (25%) or anarchist (25%)', '{"IQ":"2D6+6","ME":"3D6+3","MA":"3D6+2","PS":"3D6+8","PP":"3D6+6","PE":"4D6+4","PB":"2D4+1","Spd":"2D4x10+22"}', NULL, NULL, '3D6x10+100', '3D6x10+ME', NULL, 'Spd 2D4x10+22 is flying; 6D6 on the ground. All physical attributes are supernatural. P.P.E. adds 2D6 per level of experience. Average level 1D4+3 for NPCs (level one or two for a rare player character); uses the Dragon experience table. Bio-regenerates 3D6 M.D.C. per minute.', NULL, 13, '{"attacks":7,"initiative":4,"strike":2,"parry":2,"dodge":2,"disarm":2,"entangle":2}', 'Seven physical attacks or two spell attacks per melee round. +2 to save vs magic, +1 vs psionic attack, +3 vs Horror Factor. Punches and kicks do supernatural P.S. damage; it can use most weapons with its prehensile feet and melee weapons with its tail. The tail''s P.S. is 20% below its normal P.S.', 'Speaks Dragonese, Demongogian and American (all +30%) plus two languages of choice; literate in one (+10%); Basic Math +20%; Land Navigation +20%; Wilderness Survival +10%; Intelligence +20%; Interrogation +10%; Track +10%; Escape Artist +15%; Acrobatics +10%; Climb 90%/80%; Find Contraband +10%; two W.P.s of choice; plus three Rogue and three Espionage or Military skills of choice at +5% each.', 'Flies; prehensile tail and feet; double-jointed; nightvision 500 ft; half damage from heat and fire; bio-regenerates; supernatural strength and endurance; sees the invisible; immune to poison and disease; hangs upside down from ceilings like a bat.', 'Death Trance, Chameleon, Invisibility, Globe of Daylight, Shadow Meld, Cloak of Darkness, Horror, Influence the Beast, Frostblade and Power Weapon (the last from Rifts Federation of Magic); plus three spells of its choice from levels 1-5 at each level of experience.', 'None', '9-12 ft (2.7-3.6 m) from snout to tail tip; main body about 5 ft (1.5 m) tall at the shoulder; wingspan 15-20 ft (4.6-6 m), folding compactly like a bat''s', '600-700 lbs', 'Unknown; estimated 400-700 years', NULL, 'Powerful psychics and practitioners of magic; also dragons, demons, bandits, mercenaries and any evil force that pays', 'Anyone who is not an associate or on its side', 'An NPC villain; the book advises against it as a player character (if allowed, anarchist or evil, and distrusted by nearly everyone). 01-50% chance of carrying a lesser magic item (a potion or scroll, say); 01-30% chance of a magic or Techno-Wizard weapon. Many sit on hoards valued from several hundred thousand credits into the millions.', 'A hairless ape-like creature with a long serpentine neck, a baboon-ish head, a long tail and bat-like wings, far more dangerous than its size suggests. Clever, cruel, greedy and fond of sadistic pranks and torture, it increasingly serves mages, greater demons and evil master psychics as a henchman; several work for Lord Dunscon as his spies and killers, and as thieves.', 'Rifts World Book 12: Psyscape p.98-99'),
('land-ray', 'Land Ray', 'monster', 'rifts', 0, 'Considered anarchist or miscreant', '{"IQ":"4","ME":"3D6+6","MA":"1D6","PS":"3D6+6","PP":"2D6+10","PE":"3D6+6","PB":"2D6","Spd":"44"}', 'PEx3', 'PE+4D6', NULL, '3D6', '2D4x10+ME', 'I.Q. 4 is low animal intelligence. Spd 44 is telekinetic flight (30 mph), with dives from treetops or leaps from the water''s edge at 60 mph; swims at 20; crawls at 1D4 on land. Not a supernatural or M.D.C. creature: its protection is a Psychic Body Field (40 M.D.C. for 10 I.S.P., 8 minutes per use) and a Telekinetic Force Field, plus telekinetic blocks and parries with its tail and Psi-Sword. Found alone, in pairs or in groups of 3D6.', NULL, 10, '{"attacks":3,"initiative":2,"strike":2,"parry":1,"dodge":2,"roll":4}', 'Horror Factor 13 when a pack of 8 or more attacks. The three attacks are physical or psionic. +4 to save vs poisons and toxins; needs a 12 or higher to save vs psionic attack.', 'Swim 88%, Prowl 60%, Wilderness Survival 70%, Land Navigation 70%, Track by sight 54%.', 'Natural psionics (two head lumps are its psychic organs); prehensile tail for stabbing and whipping; nightvision 2000 ft; cold does half damage; breathes air and water and can hold its breath 1D4+10 minutes.', 'None', 'Telekinetic Flight (unlimited duration, no I.S.P. cost) and Psychic Body Field (40 M.D.C., 10 I.S.P., 8 minutes; it can use other powers, Psi-Sword included, while it is up). Also See the Invisible, Sixth Sense, Presence Sense, Bio-Manipulation, Levitation, Telekinetic Force Field, Telekinetic Lift, Telekinetic Punch (with the tail), Telekinesis (super) and a tail Psi-Sword. Proficiency equals a 4th level Master Psychic.', 'Wingspan 10 ft (3 m); 7-8 ft (2.1-2.4 m) long', '160-250 lbs (72.5-113 kg)', '25 Earth years', 'Forests, swamps and slow-moving fresh water in temperate and sub-arctic regions: the Great Lakes (Ontario included), the Magic Zone, the southeastern United States, southern Canada, Hudson''s Bay and the British Isles; avoids hot or dry climates and ranges up to 30 miles from water', 'Only other Land Rays; they form packs of 3D6 but usually hunt alone or in pairs', 'No sworn enemies; treats most humanoids and mammals as food and attacks other predators as rivals', NULL, 'An amphibious alien predator shaped like a mottled green manta ray with a long prehensile whip tail. Helpless on land without its psionics, it flies by telekinesis, strikes with a Psi-Sword projected from its tail and shields itself with psychic force fields; lone rays pick off stragglers and livestock, while packs of 6-18 will take on parties of a dozen people.', 'Rifts World Book 12: Psyscape p.101-102'),
('necrophim', 'Necrophim', 'monster', 'rifts', 0, 'Diabolic', '{"IQ":"3D6","ME":"2D6+6","MA":"1D6","PS":"2D6+30","PP":"2D6+6","PE":"2D6+12","PB":"1D6","Spd":"2D6+12"}', NULL, NULL, '1D4x100+250', '4D6', NULL, 'I.Q. is whatever the host had in life (the book says typically 3D6, stored). In humanoid disguise M.A. is +6 and P.B. becomes 22+1D4. P.S. and P.E. are supernatural. No I.S.P.: the bonded Soul Snake (its own row) holds all psionics and magic.', NULL, 15, '{"attacks":5,"initiative":4,"strike":4,"parry":1}', 'Plus one physical attack per back tentacle (1D4 of them), so 6-9 in true form; in disguise only 3 physical. Plus 10 to save vs Horror Factor; impervious to possession. Horror Factor 15 is its true form; +3 more when the Soul Snake shows itself in fury. The snake adds five psionic attacks or two spells (or one spell and three psionic) per melee, three psionic or one spell while disguised.', 'The host''s own O.C.C. or R.C.C. skills, frozen at the level it had when it bonded, with no related or secondary skills; plus Seduction +42%, two rogue skills of choice +35% and two espionage skills of choice +35%.', 'Nightvision 500 ft; exceptional hearing; prehensile tentacles (two 20 ft arm tentacles and 1D4 back tentacles of 12 ft); climb 95%/85%; leaps 10 ft high and 12 ft long (50% more running). Lust for blood: must eat human or D-bee blood and organs at least every four days, smells blood a mile off, tells whose blood it is and tracks by blood scent 72%. Metamorphosis: can take its former mortal looks or a beautiful female form for 12 hours of every 24. Shares every sense and thought with its Soul Snake.', 'None of its own; the bonded Soul Snake casts.', 'None of its own; the bonded Soul Snake uses them, and the Necrophim knows whatever the snake senses.', 'About 20% larger than its original species (around 7.5 ft / 2.3 m for a human); arm tentacles 20 ft (6 m), back tentacles 12 ft (3.6 m)', '500 lbs (225 kg)', 'Lives until destroyed', 'Anywhere in the Megaverse; scattered across Rifts Earth, most (a few dozen to a hundred) in the Gargoyle Empire, Africa, China, the Calgary Rift and the Magic Zone', 'None as such; sometimes sorcerers, Necromancers, greater demons and evil gods. Three are rumored to be among the Necromancers of Dunscon.', 'Humans, D-bees and most mortal beings (prey); Angels and Spirits of Light, Psi-Stalkers, Dog Boys, Darkhounds, Nega-Psychics and others who sense the supernatural', 'Not for player characters (NPC only, per the book).', 'A mortal who willingly bonded with a Soul Snake and was remade within 48 hours into a skull-faced mega-damage demon with lashing tentacles for arms. Usually female, it feeds on blood and organs and uses seduction as a weapon; worshipped in places as an angel of war and death. The pair together are called the "Two Who Are One".', 'Rifts World Book 12: Psyscape p.103-105'),
('soul-snake', 'Soul Snake', 'monster', 'rifts', 0, 'Diabolic', '{"IQ":"1D6+19","ME":"1D6+19","MA":"1D6+9","PS":"2D6+9","PP":"2D6+9","PE":"2D6+9","PB":"1D4","Spd":"1D6+19"}', NULL, NULL, '300+PE', 'PEx30', 'MEx20', 'Spd is slithering and climbing; it also flies at 30 mph (max altitude 1000 ft). Supernatural attributes. The book gives averages of 450 P.P.E. and 450 I.S.P. Bio-regenerates 1D6x10 M.D.C. per minute.', NULL, 15, '{"initiative":2,"strike":2}', 'Half the Necrophim''s bonuses: +2 initiative, +2 strike, and half of its +1 parry and +10 vs Horror Factor (not stored); impervious to possession. When bonded it supplies five psionic attacks or two spells (or one spell and three psionic) per melee. No attacks per melee or damage of its own are printed.', 'Swim 90%, climb 80%/60%, prowl 80%.', 'Unbonded it flies at 30 mph (1000 ft ceiling); bio-regenerates 1D6x10 M.D.C. per minute; impervious to disease and poison; at will and at no cost: turns invisible indefinitely, dimensional teleport 70%, shrinks to half size. Bonds only with willing, intelligent mortals (never M.D.C., supernatural or magic beings), attaching at the base of the skull; once bonded it is stuck on that world until its Necrophim dies.', 'Tongues, Repel Animals, Blind, Mute, Agony, Life Drain, Calling, Domination, Compulsion, Sickness, Spoil, Control/Enslave Entity, Create Zombie, Turn Dead, Dimensional Portal, Close Rift, Disrupt Energy, Electric Arc, Power Bolt, Armor Bizarre, Aura of Death, Death Curse, Deathword, Curse of the World Bizarre, Desiccate the Supernatural (the last several from Federation of Magic).', 'All Mind Bleeder, Sensitive and Super psionic powers.', '6-10 ft (1.8 to 3 m) long', '25 lbs (11 kg)', 'Lives until destroyed', 'Anywhere in the Megaverse; on Rifts Earth wherever its Necrophim is', 'Its bonded Necrophim; sometimes sorcerers, Necromancers, greater demons and evil gods', 'Most mortal beings and those who hunt the supernatural', 'Not for player characters (NPC only, per the book).', 'A dimension-hopping psychic serpent that creates the Necrophim by bonding to a willing mortal and fusing with its mind and soul. Usually hidden coiled along its host''s spine, it shows its full body only when enraged or when the host dies and it leaves to find another.', 'Rifts World Book 12: Psyscape p.103-105'),
('psymbiote', 'Psymbiote', 'alien', 'rifts', 0, 'Unprincipled (45%), anarchist (20%), miscreant (20%), other (15%)', '{"IQ":"2D6+10","ME":"3D6+6","MA":"3D6+10","PS":"1D4","PP":"1D4","PE":"1D6+2","PB":"1D4","Spd":"2D4"}', NULL, NULL, 'PEx3', '1D4x10+PE', '4D6x10+ME', 'Spd 2D4 is on the ground; underwater it is that roll x10. Average level of experience 1D4+2. A bonded host and Psymbiote pool their P.P.E. and I.S.P.', NULL, 8, '{"attacks":3,"dodge":1,"roll":2}', 'The three attacks are psionic only; it cannot fight physically beyond squirming and swimming, and a host fights with its own attacks. Without a host: +3 to save vs magic, +3 vs psionics, +2 vs Horror Factor. A host gains +1D4x10 S.D.C. (or +2D6 M.D.C. if an M.D.C. being), +1 M.E., +1 initiative, +1 save vs magic, +1 vs psionics and illusions, +2 vs Horror Factor, +5 vs toxins, poison and disease.', 'Swim 98%, climb 60%/40%, prowl 45%. When controlling a host it uses the host''s skills and magic at half proficiency.', 'Breathes air and water and lives in either indefinitely (depth limit 2 miles); impervious to cold (half from magic cold); heals at half the human rate; telepathy to 50 miles. Merge with Host: burrows under the skin of any oxygen-breathing creature with a nervous system and joins its spine, sharing senses, thoughts and psychic reserves and protecting both with its self-only psionics. Control Host: can seize the body (host saves vs psionics at -3 with no bonuses; 20 I.S.P. for 2 hours, +10 per extra hour, 12 hours max). Imperceptible Aura: see-aura never reveals it inside a host.', 'None; a host may have its own.', 'A Master Psychic: Bio-Manipulation, Super Bio-Regeneration, Telekinesis (super), Hydrokinesis, Hypnotic Suggestion, Deaden Pain, Death Trance, Mind Block, Group Mind Block, Group Trance, Healing Touch, Impervious to Fire, Levitation, Presence Sense, Psi-Sword (host only), Psionic Invisibility, Psychic Armor, Psychic Diagnosis (host only), Psychic Surgery (host only), See Aura, See the Invisible, Sixth Sense, plus two each of healing, sensitive, physical and super (no Mind Bleeder powers).', '6 to 8 inches (15 to 20 cm) long, 4 inches (10 cm) wide', '2 to 4 lbs (0.9 to 1.8 kg)', '350 years', 'Cool coastal waters; about 300,000 free in Rifts Earth''s seas (mainly the Atlantic, Hudson Bay, the St. Lawrence and the Great Lakes, small bands of 2D4+2 elsewhere) and 100,000 bonded to hosts across North America, Europe and Africa', 'The Symbiote Liberation Front and anyone fighting the Splugorth; kinship with the Zembahk and Eyes of Eylor; sometimes unsavory or evil forces', 'The Splugorth and their minions, especially High Lords, Kydians, Metztla and Slavers', 'Not a player character, per the book; may be a secondary character or bonded to an existing one. A lobotomized Psymbiote sold by the Splugorth gives its host only Sixth Sense, Mind Block and bio-regeneration, 4D6 P.P.E., 2D4x10 I.S.P., 2D6 M.D.C. and a +2 save against mind control and possession.', 'A small greenish-brown tentacled sea worm from an ocean world that the Splugorth invaded, lobotomizing millions of them as psychic batteries for bio-wizardry. The escapees formed the Symbiote Liberation Front and bond with hosts, willing or not, to fight the Splugorth; they are not evil, but have grown cold and ruthless about their survival.', 'Rifts World Book 12: Psyscape p.105-108'),
('shadeling', 'Shadeling', 'entity', 'rifts', 0, 'Diabolic (33%), miscreant (33%), anarchist (24%), other (10%)', '{"IQ":"1D4+2","ME":"1D6+8","MA":"1D4","PS":"1D6+11","PP":"1D6+8","PE":"N/A","PB":"1D6","Spd":"1D6+30"}', NULL, NULL, '2D4x10+14', '3D6x10+40', 'MEx4', 'Spd is floating and flying; it never touches the ground. P.P.E. stays the same whatever caster type it rolls.', NULL, 13, '{"attacks":3,"dodge":4}', 'Three melee attacks or three spell attacks per melee. Plus 5 to save vs magic, plus 6 vs mind control; immune to Horror Factor. Its punch does double damage to supernatural beings and creatures of magic.', 'Seems to understand all languages somewhat but rarely speaks.', 'Made of energy: floats and flies, nightvision 500 ft, regenerates 3D6 M.D.C. per melee; unaffected by disease, radiation, pollution, gases, poison and Horror Factor; immune to most physical attacks; fire, heat and energy do half damage and cold none; magic, magic weapons, constructs and creatures of magic hurt it normally. Sends out empathic waves of fear, sorrow and hate.', 'Cloak of Darkness, Manipulate Objects, Repel Animals, Befuddle, Energy Bolt, Fingers of Wind, Fuel Flame, Wave of Frost and Horror; plus the spells of a 1D4 level caster rolled on percentile: 01-35 Ley Line Walker, 36-56 Fire Warlock, 57-60 Necromancer, 61-75 Air Warlock, 76-85 Conjurer, 86-95 Temporal Wizard, 96-00 any Magus O.C.C.', 'Sense Magic, Empathy, Empathic Transmission, Mind Bolt.', '6-7 ft (1.8 to 2.1 m) tall', 'Negligible; made of energy', 'Unknown; possibly immortal, possibly a few years', 'The Magic Zone and the Calgary Rift only', 'None, not even other Shadelings; rarely troubles evil supernatural beings', 'Feared by most mortals; hates all things beautiful and good', 'Not for player characters (NPC only, per the book): mindless and evil.', 'A featureless black humanoid of shimmering energy found only in the Magic Zone, perhaps the lingering imprint of a slain evil spell caster or dark emotion made real. Most haunt and torment whoever they meet, luring victims into danger and attacking with magic; a few oddly lead people to safety. It barely speaks, and only in single harsh words.', 'Rifts World Book 12: Psyscape p.108-109'),
('lipoca-sun-demon', 'Lipoca, Sun Demon', 'demon', 'rifts', 0, 'Diabolic (33%), miscreant (33%) or anarchist (24%); 10% other alignments', '{"IQ":"1D6+14","ME":"1D6+12","MA":"1D6+14","PS":"1D6+22","PP":"1D6+12","PE":"1D6+12","PB":"1D6","Spd":"1D6+14"}', NULL, NULL, 'PEx100', '4D6x10+PE', 'MEx10', 'M.D.C. also gains 1D6x10 per level of experience; P.P.E. gains 25 per level; I.S.P. gains 10 per level. Spd is running on the ground and doubles when it runs on all 6-8 limbs. Physical attributes are supernatural. Average level of experience (NPC) 1D4+5.', NULL, 13, '{"attacks":6,"initiative":4,"strike":3,"parry":6,"dodge":2,"pull":3,"roll":2}', 'Attacks: 6 physical, or 6 psionic, or 2 magic, or a mix of the three (at most one magic, two psionic and two physical in one round). Critical strike on a natural 19-20. Plus 8 to save vs possession, plus 1 on all saving throws, impervious to Horror Factor. Bonuses are on top of attribute bonuses.', 'R.C.C. skills: Seduction +30%, Basic Math +30%, Intelligence +20%, Interrogation +20%, Cardsharp +15%, Escape Artist +15%, Find Contraband +15%, Streetwise +12%, Detect Ambush +10%, Swim +10%; Demongogian and Dragonese at 98% plus one more language (+10%); three lore skills of choice (+10%). Prefers its own powers and cunning to man-made weapons and devices.', 'Sees in the dark to 1000 ft (305 m); heals 2D6 M.D.C. each melee round, regrows its head tentacles in a day and an eye or leg in three days; fire and heat do half damage; unaffected by disease, poison, gas, radiation, pollution and Horror Factor; Dimensional Teleport 42% plus 2% per level. Its two small central eyes act as a psychic third eye that sees the invisible, spirits, astral beings, auras and the glow of magic items, spell casters and creatures of magic, at no I.S.P. cost. Climbs walls and walks on ceilings like an insect at its normal speed (half on glass-smooth surfaces).', 'Every Necromancy spell, plus: Animate and Control Dead, Befuddle, Chromatic Protection, Cloak of Darkness, Death Curse, Death Trance, Dimensional Portal, Ensorcel, Fire Ball, Fire Bolt, Fuel Flame, Globe of Daylight, Ignite Fire, Impervious to Fire, Lantern Light, Light Target, Lightblade, Manipulate Objects, Metamorphosis: Human, Metamorphosis: Insect, Negate Magic, Null Sphere, Repel Animals, See in Magic Darkness, Soultwist, Throwing Stones, Tongues, Turn the Dead. Also 1D4 spells from each of spell levels 4, 5 and 6.', 'Master psionic: every Sensitive and Healing power, plus Hypnotic Suggestion, Mentally Possess Others, Mind Bond, Mind Wipe, Psionic Invisibility, Psychic Omni-Sight (printed "Omini-Sight") and Telemechanics.', '8 to 10 ft (2.4-3 m) tall', '500 lbs (226 kg)', 'Immortal, but can be killed', 'At least two are in the Orient and one works the Magic Zone; as many as a dozen may be lured to Rifts Earth by its many portals', 'None as such; recruits Necromancers, death cults and evil or selfish beings of any kind, even good ones who serve its purpose or amuse it', 'Many, from mortal heroes to supernatural beings', 'Not for player characters (NPC only, per the book). Also called the Devouring Sun, and poses on Earth as the Toltec god Tezcatlipoca, God of the Smoking Mirrors, or one of his children.', 'Demigod-class supernatural beings, seldom more than a handful to a world, who pass themselves off as gods and delight in building up a faction only to watch it collapse in atrocity and war. Stands on two insect-like legs with four arms, a pale yellow chitin shell and a round head ringed by 18-24 thin tentacles like sun rays; eats humans and D-bees and wears their bones as ornaments.', 'Rifts World Book 12: Psyscape p.109-113'),
('vyarnect', 'Vyarnect', 'demon', 'rifts', 0, 'Diabolic or miscreant only', '{"IQ":"2D4+4","ME":"3D6","MA":"2D6","PS":"5D6+20","PP":"3D6+4","PE":"4D6+10","PB":"1D4","Spd":"3D6+10"}', NULL, NULL, '4D6x10+60', '2D4x10', 'MEx4', 'All physical attributes are supernatural. Has P.P.E. yet casts no magic. Packs: small 1D4+2, medium 1D6+5, large 2D6+8.', NULL, 14, '{"attacks":5,"initiative":3,"strike":4,"parry":2,"dodge":6}', 'Plus 5 to save vs poison and disease, plus 3 vs magic; in addition to attribute bonuses. Frenzied by foes who flee or show fear: +1 attack per melee, +1D6 M.D. per attack, and +2 on saves vs Horror Factor and vs fear from magic or psionics. Facing a fearless foe it cannot quickly beat: -2 initiative, -1 attack per melee, and -2 on saves vs fear and Horror Factor; it soon runs. Never uses weapons or wears armor.', 'Climb 95/90%, Prowl 45%, Acrobatics at base skill +10%. Speaks only a heavily guttural Demongogian (60%) that non-demon speakers of the tongue understand at half their skill.', 'Nightvision 500 ft (152 m); sees the invisible; supernatural strength and endurance; leaps 15 ft (4.6 m) up or 25 ft (7.6 m) across, twice that with a running start; bio-regenerates 1D6x10 M.D. per hour; fire and heat do half damage; silver M.D. weapons do double damage and silver S.D.C. weapons do their S.D.C. as M.D.; immune to poison.', 'None', 'Bio-Manipulation, Levitation, Telekinetic Leap, Telepathy.', '10 to 12 ft (3-3.6 m) tall', '1500-2000 lbs (675 to 900 kg)', 'Presumed immortal, as a sub-demon', 'Origin unknown; most live along the Mississippi and in the Magic Zone, probably having come through the Devil''s Arch at St. Louis before the CS walled it off', 'Drawn to powerful evil beings: Necromancers, Shifters and above all demons. Lord Dunscon of the Federation of Magic keeps a secret army of 1000.', 'All but demons and those who keep company with them', 'Not for player characters (NPC only, per the book).', 'Dim-witted sub-demons, or perhaps ape-like mega-damage beasts from another dimension, with gorilla-like bodies, hand-like feet, a cactus-like prehensile tail and a canine head made for crunching bone. They run in mobs that follow whoever leads, serve as shock troops for smarter evil, and are prized by Necromancers because they eat the dead.', 'Rifts World Book 12: Psyscape p.113-115'),
('power-leech', 'Power Leech', 'alien', 'rifts', 0, 'Any; typically anarchist (55%) or evil (35%)', '{"IQ":"2D6+5","ME":"3D6+5","MA":"2D6+3","PS":"2D6","PP":"2D6+5","PE":"2D6+1","PB":"3D6+5","Spd":"2D6+5"}', NULL, NULL, '2D6+PE', '5D6', 'ME+1D4x10', 'M.D.C. gains 1D6 per level of experience; I.S.P. gains 2D4 per level. Physical attributes are supernatural. GROWTH: for every 100 M.D. (or 100 P.P.E.) absorbed within an hour it adds 1D4x10+20 M.D.C., grows 20% in size and weight, gains 1D4 P.S., 1.5 Horror Factor and 2D6+10 I.S.P., and bio-regenerates 2D6 M.D. per minute; the excess burns off within 48 hours. Average level of experience 1D4+2.', NULL, NULL, '{"strike":1,"parry":2,"dodge":2,"roll":4}', 'Horror Factor: none in natural form, rising as it grows. Attacks per round are by hand to hand skill plus one from the R.C.C. Plus 1D4+2 to save vs magic; +5% to skills needing manual dexterity (such as escape artist, pick locks, demolitions, and mechanical or electrical work). Saves as a major psychic (12 or better).', 'R.C.C. skills: native tongue 98%; two Earth languages (+10%); Climbing +20%; Land Navigation, Prowl and Palming +10% each; W.P. Paired Weapons, one other W.P. of choice, and Hand to Hand: Basic (Expert costs two other skills). Four related skills at level one and two more at levels 3, 7, 11 and 15; two secondary skills at levels 1, 5 and 10.', 'Small and nimble with rubbery M.D. skin; ambidextrous. Energy Absorption: soaks up energy by touch or within 5 ft (1.5 m), including ley line P.P.E. (15 per hour), batteries, E-clips, power plants and power armor reactors; all energy aimed at it (blasts, radiation, nuclear or magic fire) is absorbed instead of hurting it. Rough yields: flashlight battery 0.25 M.D., car battery 2 M.D., E-clip about 200 M.D. (long clip 300), a nuclear power armor or vehicle about 2,000 M.D. drained at 200 per minute, a city''s power supply 200 M.D. per minute. Drains up to 20 P.P.E. per melee round from a mage, dragon or P.P.E. battery nearby (not rune weapons or most Techno-Wizard items). A spell aimed at it or catching it in an area is eaten unless the caster saves vs psionics at -4; on a save it has one-third effect. A mage casting while being drained must save the same way or lose the spell and its P.P.E.', 'None', 'Major psychic: Mind Bolt (super), Mind Block, See Aura, Sense Magic, Telekinetic Punch, Telekinetic Push, plus two healing or physical powers of choice.', '2.5 to 4 ft (0.8-1.2 m); grows as it absorbs energy', '50 to 80 lbs (22.7 to 36.3 kg); grows as it absorbs energy', '90-110 years', 'Scattered across the Megaverse; under a hundred on Rifts Earth, about a third of them roaming North America', 'Most of the clans that came to Earth are citizens of Psyscape; individuals befriend any beings of like alignment', NULL, 'Written as an R.C.C., but the book''s NPC block says it is not meant for players (NPC only). Money 3D6x100 credits plus 2D4x1000 in black market goods; takes no cybernetics. Gear: durable clothes, utility belt, backpack, survival knife, canteen; maybe a Vibro-Knife and energy pistols with 1D4 extra E-clips. Likes sweet and salty snacks.', 'Short, spindly D-bees with oversized heads, big sad eyes and pot bellies who look like playful children and enjoy the company of children, yet rank among the most dangerous predators on Earth. On their solar-flare-wracked homeworld they feed on energy through their skin; about a hundred were stranded on Rifts Earth, where gorging on energy swells one into a titan while its foes are left drained and powerless.', 'Rifts World Book 12: Psyscape p.126-128'),
('darkhound', 'Darkhound', 'mutant', 'rifts', 1, 'Any, but typically Anarchist (33%), Unprincipled (23%) or Aberrant (24%); a bloodthirsty predator toward psychics, mages and the supernatural whatever its alignment', '{"IQ":"2D4+2","ME":"2D6+8","MA":"2D4+1","PS":"3D6+10","PP":"3D6+6","PE":"2D6+10","PB":"2D4","Spd":"6D6+10"}', NULL, NULL, '3D6x10', '2D6', 'ME+1D6x10', 'A mega-damage creature: M.D.C. 3D6x10, +2D6 per level of experience. I.S.P. +10 per additional level; regained 2 per hour of activity or 12 per hour of meditation or sleep. P.P.E. 2D6 is the permanent base. Physical attributes are supernatural. About half wear scrap-built partial body armor, typically 1D4x10+15 M.D.C.', NULL, 11, '{"attacks":5,"initiative":2,"strike":1,"pull":3,"roll":1}', 'Horror Factor rises to 14 against supernatural beings and practitioners of magic, especially the True Federation. Attacks are the equivalent of Hand to Hand: Expert (four at level one) plus the racial +1; the racial +2 initiative recurs at levels 4, 8 and 14 and +1 attack at levels 5 and 10. Saves: +4 vs Horror Factor, +3 vs disease and poison, +2 vs possession; needs 10 or higher to save vs psionics as a master psychic. Magic resistance: even on a failed save, magic''s damage, duration and penalties are halved.', 'Land Navigation (+20%), Wilderness Survival (+20%), Climb (+15%), Swim (+20%), Prowl (+10%), Intelligence (+5%), W.P. Sword or Knife; speaks American at 45% +3% per level and may pick up one more spoken language at 35% +3% per level; cannot read or write. Four secondary skills without bonuses, limited to Physical (any), Technical (spoken languages and lore only) and Wilderness (any). Combat equal to Hand to Hand: Expert.', 'Senses psychic and magic energy like a keener Psi-Hound (70% +2% per level; 50 ft +5 ft per level for an idle psychic or mage, 1000 ft +50 ft per level for powers in use) and can trace it to its source; recognizes psychic scents (20% +4% for a race, 14% +2% for an individual); senses supernatural beings and possession (72% +2%; tracks them at 50% +5%, or 70% +3% if they use powers). Dog Boy sense of smell (tracks by smell alone 40% +4%), very keen hearing, 270 degree vision but no nightvision. Immune to animal affinity and control powers. Ley lines and nexus points blind its psychic senses, and ley line energy and lightning hit it twice as often as others. Cannot take cybernetics.', 'None.', 'Master psychic: Sense Evil, Sense Magic, Deaden Senses, Nightvision, Resist Fatigue and Empathy (receiving only), plus one Sensitive power of choice.', '8 or 9 ft (2.4 to 2.7 m) tall', '400 to 500 lbs', 'Unknown; perhaps 30 to 40 years', 'Wilderness of the Magic Zone, Ohio and the lower Great Lakes; hunts at night in packs of 4D4, sometimes with mixed groups of Dog Boys, humans and animal-like D-bees', 'Seldom attacks Dog Boys, Coalition soldiers or innocent humans, and has fought beside CS troops against supernatural horrors', 'Practitioners of magic above all, then evil supernatural beings, powerful psychics, creatures of magic such as faeries and dragons, and monsters; anything warm and living is potential food', 'R.C.C. with its own skills and no O.C.C.; an NPC villain and optional player R.C.C. with the intellect of a small child. Uses no guns; starts with one Vibro-Blade and a knife, and no money. Average NPC level 1D4. The book says to use the Juicer experience table, while its experience-tables page lists it with the Psi-Druid and Psi-Ghost.', 'Huge grey-furred canine hunters of the Magic Zone with long gorilla-like arms and glowing red eyes, rumored to be Dog Boys twisted by Lord Dunscon''s allies. They hunt mages, psychics and the supernatural with obsessive hatred but shadow Coalition patrols and have even defended soldiers and children.', 'Rifts World Book 12: Psyscape p.94-98'),
('dragon-cat', 'Dragon-Cat', 'monster', 'rifts', 1, 'Any, but most (68%) are Scrupulous or Unprincipled', '{"IQ":"1D6+5","ME":"2D6+6","MA":"2D6+6","PS":"4D6+12","PP":"2D6+18","PE":"3D6+10","PB":"2D6+10","Spd":"3D6x10"}', NULL, NULL, 'PE+4D6x10', 'PE+2D4x10', '1D6x10', 'A mega-damage creature: M.D.C. 4D6x10 + P.E., +3D6 per level of experience. I.S.P. is printed "1D6x10+10 per level", read as 1D6x10 at first level and +10 per level after. Supernatural attributes. Bio-regenerates 1D6 M.D. per hour.', NULL, 12, '{"attacks":5,"initiative":3,"strike":4,"parry":3,"dodge":3,"roll":5,"pull":2}', 'Five physical or psionic attacks per melee, or two by magic. Saves: +1 vs magic, +5 vs psionics, +6 vs Horror Factor. Its bonded rider gains +20% Exotic Horsemanship on it, one extra attack while riding, +2 initiative, +1 strike and parry, and +6 M.D. on charging melee attacks.', 'The book prints no skills. Prowl 70%, climb 65%, swim 50%, gymnastics 70% and track by smell 46% are natural abilities.', 'Nightvision 1000 ft (305 m); prowl 70%, climb 65%, swim 50%, gymnastics 70%, track by smell 46%; leaps 20 ft high or 30 ft long (50% more with a run); half damage from fire and heat; bio-regenerates 1D6 M.D. an hour; senses the supernatural within 500 ft like a Dog Boy. Cannot speak and talks by telepathy (3000 ft). Forms a telepathic bond with one trusted rider or friend: free, secure telepathy within 3000 ft and near-perfect teamwork. Never uses technology.', 'Only its innate spells: Blinding Flash, Breathe Without Air, Climb, Cloud of Smoke, Repel Animals, Shadow Meld, Turn Dead, Manipulate Objects and Sustain, always cast at the strength of a 3rd level Ley Line Walker.', 'Equivalent to a master psychic with limited powers: Impervious to Cold, Mind Block, Presence Sense, Resist Fatigue, Resist Hunger, Resist Thirst, See Aura, Telepathy and Telekinetic Push, plus one Physical, one Sensitive and two Healing powers of choice.', '8 to 10 ft (2.4 to 3 m) tall and 15 to 20 ft (4.6 to 6.1 m) long, including a 5 to 8 ft tail', '1200 to 1800 lbs (544 to 816 kg)', '200 to 300 Earth years', 'Dusty savanna worlds originally; on Earth the American Northwest and Western Canada, especially the Lone Star-Oklahoma border, the Calgary Rift region and the Ohio Valley/Magic Zone; fewer than about 1000 in North America', 'Honorable beings of like ethics; favored riders are Mystical Indian Warriors, Wilderness Scouts, Cyber-Knights, Simvan, Psi-Druids and Psi-Warriors; also likes Dog Boys and most psychics', 'Evil in all forms, especially evil Shifters, demons, Deevils and other predators of the weak; slavers above all', 'Optional player character, likely only first or second level when played; no O.C.C., skills, equipment or money are printed. Average NPC level 1D4+3.', 'A ten-foot, six-legged predator that looks like a cross between a hunting cat and a dinosaur, with a scaly mega-damage hide. It is an intelligent creature of magic with a knightly code of honesty and fair play, and often volunteers as mount and partner to heroes it respects.', 'Rifts World Book 12: Psyscape p.99-101'),
('amorph', 'Amorph', 'entity', 'rifts', 1, 'Any, but usually Unprincipled (36%) or Anarchist (30%)', '{"IQ":"2D4+4","ME":"2D6+6","MA":"2D6+12","PS":"1D6+4","PP":"1D6+6","PE":"2D6+6","PB":"1D4","Spd":"2D4+4"}', 'PE+3D6x10', NULL, NULL, '2D6', 'ME+1D4x10', 'S.D.C. and hit points are one combined pool: P.E. + 3D6x10, +2D6 per level of experience; it is not an M.D.C. being. I.S.P. +10 per level. P.B. 1D4 is the natural form; shape changing gives any P.B. from 2 to 24. Spd is walking and flying. Bio-regenerates 1D6 S.D.C. per melee round (2D6 on the Astral Plane). Feeds on about 21 P.P.E. a week.', NULL, NULL, NULL, 'No Horror Factor in its natural form; when shape-changed it has that of the creature mimicked. Saves: +6 vs Horror Factor, +6 vs possession, needs 12 to save vs psionics; +10% to charm/impress. Automatic dodge that costs no attack, +1 at levels 3, 6, 9 and 12; suppressing it to keep a disguise costs one attack and -1 to all combat rolls that melee.', 'Two languages of choice (+15%), Dance (+20%), Climb (+10%), Land Navigation (+25%), Lore: Astral Plane (+15%), one lore of choice (+10%), Hand to Hand: Basic (cannot be upgraded). Four related skills plus one at levels 4, 8 and 12: Communications, Domestic, Espionage, Science and Pilot Related any; Pilot (+5%); Rogue (+10%) except Computer Hacking; Technical (+5%) except Computer Programming; Medical First Aid and Holistic Medicine only; W.P. Blunt, Knife and Energy Pistol only; no Electrical, Mechanical, Military, Physical or Wilderness. Five secondary skills from the same list.', 'Ectoplasmic metamorphosis: copies the look and texture of any creature or object it can see, from cat-sized to dragon-sized, but not its voice, powers, M.D.C. or weight; psionic sensing can expose it. Floats and flies at will up to 50 ft above ground, flattens to paper thickness or narrows to a pencil''s width. Needs no food, water or air; sees the invisible, senses ley lines and Dragon Roads at 1 mile (10 on the Astral Plane), understands all languages through telepathy, impervious to disease, poison and pollution. Cold, heat and fire hurt it normally. Cannot take cybernetics.', 'None.', 'Natural psychic: Telepathy, Empathy, Presence Sense, Sense Evil, Sense Magic, Commune with Spirits, Alter Aura, Ectoplasm, Psychic Body Field, Telekinetic Force Field and Psychic Omni-Sight, plus two Sensitive or Physical powers at levels 2, 4, 8, 12 and 15.', 'Varies at will, from a cat to an adult dragon', '45 to 60 lbs (20.4 to 27.2 kg), whatever its size', 'Immortal unless slain', 'The Outer Layer of the Astral Plane; hundreds visit Psyscape''s City of the Mind''s Eye each week and some settle there', 'Deals fairly with everyone and goes to great lengths for friends and kindred spirits', NULL, 'R.C.C. with its own skills; optional player character, not advised (G.M. discretion). Starts with simple traveling gear, a conventional weapon and an energy weapon, and 1D6x100 credits.', 'Sentient blobs of living ectoplasm from the Astral Plane who can mimic almost any creature or object. Friendly, nosy and endlessly curious, they can die of boredom, and many now wander Psyscape''s City of the Mind''s Eye as naive tourists snapping pictures.', 'Rifts World Book 12: Psyscape p.117-120'),
('demon-dragonmage', 'Demon-Dragonmage', 'demon', 'rifts', 1, 'Young: any, usually Anarchist (40%) or evil (40%). Adults are mostly evil (about 15% Aberrant, 15% Anarchist, only 6% good)', '{"IQ":"2D6+8","ME":"2D6+10","MA":"2D6+12","PS":"2D6+16","PP":"2D6+10","PE":"2D6+10","PB":"2D6+3","Spd":"2D6+16"}', NULL, NULL, 'PEx10', 'PE+1D4x100', 'ME+2D4x10', 'Attributes and pools are the Young-Dragonmage''s. A mega-damage creature: M.D.C. P.E. x10, +3D6 per level. P.P.E. +3D6 per level. I.S.P. +10 per level. ADULT: after slaying a dragon and joining its head to its chest, the mature Demon-Dragonmage gains +1,200 M.D.C., doubles its P.P.E., raises I.Q., M.E., M.A., P.P. and P.E. by 30%, doubles P.S. and Spd, gains wings and flight, and its Horror Factor becomes 15.', NULL, 10, NULL, 'Level abilities: +2 roll at 2nd; +1 attack, +1 initiative, +2 pull punch and +3 save vs Horror Factor at 5th; +6 save vs possession at 8th. Combat is by skill and training. Magical cold and ice do double damage; magic, psionics and energy weapons do full damage.', 'Demongogian and Dragonese at 98% plus two languages (+15%), one literacy (+15%), Basic Math (+20%), Seduction (+13%), Dance (+20%), Sing (+10%), Climb (+10%), Land Navigation (+10%), Lore: Demons & Monsters (+20%), one lore (+10%), two Pilot or Horsemanship skills, one ancient and one modern W.P., Hand to Hand: Expert (Assassin if Anarchist or evil), never upgraded. Five related skills plus one at levels 4, 8 and 12: most categories open, Rogue and Technical +10%, several +5%; no Mechanical, Medical or Wilderness (the page scrambles the Communications/Domestic/Electrical labels). Two secondary skills at levels 1, 3, 5, 8, 11 and 15.', 'Impervious to ordinary heat and fire, M.D. plasma included; magic fire does half (adults are immune even to magic fire). Gains powers by level: nightvision 1000 ft, see the invisible, fast healing and immunity to disease (1st); leap 10 ft (2nd); invisibility at will (3rd); bio-regenerates 1D6 M.D.C. per melee (4th); speaks all languages (6th); senses ley lines (7th); teleports self and 300 lbs up to five miles (9th); becomes a Greater Demon with Dimensional Teleport 30% +2% per level (10th). Adults breathe fire and spit fire balls. Cannot take implants or bionics.', 'Casts like a Ley Line Walker without that O.C.C.''s other abilities: starts with Blinding Flash, Ignite Fire, Fuel Flame, Fire Bolt and Fire Ball plus 3D4+8 spells from levels 1-6, learns more as a Line Walker does, and from 10th level may learn Temporal Magic.', 'Master psychic: Pyrokinesis, Bio-Manipulation, Telepathy and Mind Block at first level; each later level one Super power plus three from Healing, Sensitive or Physical.', '6 to 7 ft (1.8 to 2.1 m) tall; the mature Demon-Dragonmage doubles in size', '200 to 250 lbs (90 to 112.5 kg); triple as a mature adult', 'Immortal unless slain; youth typically lasts 1000 to 2000 years', 'Wanders the Megaverse as an adventurer or bandit when young; adults build kingdoms or conquer worlds', 'Other supernatural beings, psychics and practitioners of magic; adults gather lesser races such as goblins, Psi-Goblins, orcs, ogres and sub-demons as worshippers', 'All dragons, who often kill them on sight; also Temporal Raiders, True Atlanteans (especially Undead Slayers and the Sunaj) and, less so, the Splugorth; beings of light, angels and spirits distrust them', 'R.C.C. with its own skills; a player character is a Young-Dragonmage, a difficult option not advised (G.M. discretion). Starts with basic adventuring gear, two weapons for its W.P.s and 1D6x1000 credits. Average NPC level: young 1D4+4, mature 15-25. Uses the dragon experience table.', 'Probably demons from another dimension: pale, hairless humanoids with thick bony skulls who wander the Megaverse for centuries gathering magic and psionic power. To mature, one must slay a young dragon and graft its head to its own chest, becoming a winged, fire-eyed Demon-Dragonmage, which makes dragons their mortal enemies.', 'Rifts World Book 12: Psyscape p.120-123'),
('lanotaur-hunter', 'Lanotaur Hunter', 'alien', 'rifts', 1, 'Any, but Anarchist or evil are most common; many (55%) are Aberrant with a strict hunter''s honor', '{"IQ":"2D6+8","ME":"3D6+8","MA":"1D6+1","PS":"2D6+14","PP":"1D6+20","PE":"3D6+8","PB":"2D6","Spd":"2D6x10+18"}', NULL, NULL, 'PE+3D6x10', 'PEx3', 'ME+1D6x10+10', 'A mega-damage creature: M.D.C. P.E. + 3D6x10, +2D6 per level. P.P.E. P.E. x3, +3D6 per level. I.S.P. 1D6x10+10 + M.E., +2D6 per level. Supernatural attributes. Heals twice as fast as a human.', NULL, 12, '{"attacks":8,"initiative":8,"strike":4,"parry":5,"dodge":7,"disarm":3,"pull":5,"roll":4}', 'Combat equal to Hand to Hand: Martial Arts (four attacks at level one) plus four more racial attacks, with Paired Weapons, Kick and Leap Attack from first level; psychic reflexes are already in these bonuses. Automatic dodge against all attacks, even from behind. Saves: +6 vs Horror Factor, +2 vs lethal and non-lethal poisons; a master psychic but -2 vs psionics (needs 12).', 'No R.C.C. skill list is printed beyond its combat training. Swim 60%, climb 80%/70%, prowl 50% +2% per level and track by sight 44% +4% per level are natural abilities.', 'Senses psychic and magic energy like a Psi-Stalker (50 ft +20 ft per level for an idle psychic or mage; 600 ft +100 ft per level for powers in use). Psychic reflexes and combat awareness let it read opponents'' intentions, except against Mind Block. Can mask its heat signature (IR optics fail beyond 200 ft), cut its scent (-20% to track), beat any lie detector and feign a coma or death trance. Nightvision 100 ft, ambidextrous, swim 60%, climb 80%/70%, prowl 50% +2%, track by sight 44% +4%, heals twice as fast as humans.', 'Limited: Invisibility (superior), Chameleon or Shadow Meld, Dimensional Portal, Close Rift, Mystic Portal, Time Hole, Sanctum, Anti-Magic Cloud, Astral Hole, Warp Space, Swap Places, Lifeblast, Magic Shield, Lightblade, Enchant Weapon and Restore Life; above 5th level, 1D4+2 more spells from levels 7-11.', 'Master psychic: Mind Block Auto-Defense, Presence Sense, Sixth Sense, Death Trance, Telepathy, Read Dimensional Portal, Deaden Senses and Alter Aura; 1D4 Physical at 2nd, 1D4 Sensitive at 3rd, Psi-Sword and one Super at 4th, Bio-Regeneration (super) and one Super at 5th, then one Sensitive or Physical per level.', '8 to 9 ft (2.4 to 2.7 m) tall', '600 to 800 lbs (272 to 363 kg)', '80 to 120 Earth years', 'Forests from mixed woodland to rain forest, especially with giant trees; North and South America, Southeast Asia and Africa, with the Magic Zone, Calgary, the Congo and China favorite hunting grounds', 'None as such, even among its own kind; respects Psi-Stalkers, Darkhounds and Dog Boys as kindred spirits', 'No declared enemies; every life form is potential prey, and it fiercely defends a claimed hunting ground against loggers, farmers and developers', 'R.C.C.; the book heads it as an NPC villain and prints no player note, so it is playable only with G.M. permission. Relies on claws, tail and powers; will pick up basic melee weapons and magical constructs, but shuns magic weapons as unsporting.', 'Hulking supernatural D-bee sport hunters, something like a Psi-Stalker crossed with a Juicer, who treat Rifts Earth as a hunting preserve. They stalk psychics, mages and other worthy prey with psionics and blinding reflexes, favor fair challenges, and sometimes spare a foe they come to admire.', 'Rifts World Book 12: Psyscape p.123-126'),
('psi-goblin', 'Psi-Goblin', 'humanoid', 'rifts', 1, 'Any, but most are anarchist (35%), miscreant (32%) or diabolic (30%)', '{"IQ":"1D6+8","ME":"2D6+8","MA":"1D6","PS":"2D6+12","PP":"2D6+12","PE":"2D6+12","PB":"2D6","Spd":"6D6"}', 'PE+6D6', '1D4x10', 'PE+6D6+10', '3D4x10+PEx2', '1D6x10+MEx2', 'On Rifts Earth (and Wormwood) a mega-damage being with supernatural P.S. and P.E.: M.D.C. P.E. +6D6+10, +1D6 per level. The Hit Points (P.E. +6D6, +1D6 per level) and S.D.C. 1D4x10 apply only on its native world and other low-magic places. I.S.P. +1D6 per level; P.P.E. does not grow with experience. Bio-regenerates 2D6 points an hour.', NULL, 11, '{"initiative":3,"strike":2,"disarm":3,"pull":4,"roll":2}', 'Combat is Hand to Hand: Expert (cannot be changed) plus one extra hand to hand attack per melee round; attacks per melee are not otherwise printed. +2 roll covers impact or fall. Saves: +6 vs Horror Factor, +2 vs magic, +3 vs poison, radiation and pollution; impervious to disease. Needs a 12 or higher to save vs psionic attack.', 'Gobblely and Faerie Speak 98%; one more language of choice, typically American (+10%); Escape Artist (+20%), Interrogation (+20%), Intelligence (+10%), Streetwise (+10%), Land Navigation (printed as 10%), Wilderness Survival (+15%); W.P. Paired Weapons, Targeting, Knife or Sword, one Ancient, one Energy Weapon and one of choice; Hand to Hand: Expert; plus 1D4 Espionage, 1D4 Rogue and 1D4 Technical or Wilderness skills. No secondary skills.', 'Supernatural strength and endurance on Rifts Earth; double-jointed; nightvision 1000 ft (305 m); swim 55%, climb 80%/70%; bio-regenerates 2D6 points an hour, a lost finger or ear grows back within 72 hours, a whole limb within 1D4 weeks; impervious to disease.', 'Innate: each of Shadow Meld, Armor of Ithan, Fool''s Gold, Repel Animals, Energy Bolt, Force Bonds and Frostblade three times per 24 hours.', 'Major psychic: Detect Psionics, Death Trance, See the Invisible, Sense Magic, Sense Evil, Mind Block and Ectoplasm, plus two Physical powers of choice.', '4 to 5 ft (1.2 to 1.5 m)', '90 to 120 lbs (40.8 to 54 kg)', '1000+ Earth years', 'Mainly the Magic Zone, with a tribe of about sixty in the ruins of Old Chicago and a hundred or so in the Pecos Empire; prefers forest, mountain and canyon country', 'Mostly their own kind, in groups of 6-24; sometimes Black Faeries, demons, semi-intelligent monsters, Necromancers, evil mages of 6th level or higher, Mind Bleeders and powerful evil psychics', 'Humans and champions of light, and anyone who defeats, hurts or humiliates them (a lifelong grudge)', 'R.C.C. with its own skill package; the book names no O.C.C. and gives no secondary skills. NPCs average level 3-7; a player character begins at first or second level, with G.M. permission (usually unprincipled or anarchist).', 'Small, fanged, savage D-bees from a magic-rich world where they prey on Faerie Folk; many are thought to have been brought to Earth by Lord Dunscon, who fields two thousand of them. Jealous, greedy and cruel, they are feared as torturers and interrogators and work as mercenaries, bandits, spies and assassins in the Magic Zone. On Rifts Earth they become mega-damage beings with innate magic and psionics.', 'Rifts World Book 12: Psyscape p.128-130'),
('yhabbayar', 'Yhabbayar Bubblemaker', 'humanoid', 'rifts', 1, 'Almost always good: 50% scrupulous, 26% principled, 20% unprincipled, 4% anarchist or other', '{"IQ":"2D6+8","ME":"2D6+8","MA":"3D6+12","PS":"2D6+8","PP":"2D6+10","PE":"2D6+8","PB":"2D6","Spd":"5D6"}', 'PE+3D6', '5D6', 'PE+4D6', '2D4x10+PE', '4D4x10+ME', 'On Rifts Earth a mega-damage being with supernatural P.S. and P.E.: M.D.C. P.E. +4D6, +1D6 per level. Hit Points (P.E. +3D6, +1D6 per level) and S.D.C. 5D6 apply on its home world, the Astral Plane and other low-magic places. P.P.E. +3D6 per level, and it draws P.P.E. from ley lines, nexus points and people like a Line Walker. I.S.P. +15 per level.', NULL, NULL, '{"initiative":1}', '+1 initiative at levels 1, 3, 5, 7, 9, 11 and 13 (the level-one point is stored). Saves: +2 vs Horror Factor, +5 vs possession, +1 vs poison and disease. Master psionic: needs a 10 or higher to save vs psionics. While in the open trance, +8 to save vs psionic attack and +4 vs magic. Hand to Hand: Martial Arts; no attacks per melee or damage printed.', 'Speaks and reads American (+25%) and speaks one more language (+20%); Basic and Advanced Math (+25%); Art (+15%, professional quality); Sing or Play Musical Instrument (+15%); Lore: Demons & Monsters and one lore of choice (+10% each); Wilderness Survival, Land Navigation, Climbing and Swimming (+10% each); Boxing or Wrestling; W.P. one Ancient and one Energy Weapon; Hand to Hand: Martial Arts (cannot be changed). Six related skills plus one at levels 3, 6, 9, 12 and 15; three secondary skills plus one at levels 3, 6, 9 and 12.', 'An opened psychic Third Eye; senses supernatural evil automatically (300 ft +50 ft per level) and recognizes possession and magic enchantment (70% +3% per level); can open itself to the supernatural as a medium, becoming invisible to psionic probes and hard to see (50% +5% per level); senses life, pregnancy and supernatural good (100 ft +25 ft per level). Bubble Magic: in a meditative trance it floats with Psychic Omni-Sight to 500 ft and blows one magic bubble per melee action holding a psi-power or spell it knows, released when the bubble touches its target.', 'Mystic-style intuitive spells: all level one spells plus Float, Fly as the Eagle, Befuddle, Breathe Without Air, Magic Pigeon, Tongues, Life Source, Restore Limb and Mystic Portal; 1D4+1 more each level from spell levels up to one above its own. Cannot be taught or buy spells; may use Techno-Wizard devices and scrolls.', 'Master psionic: all Healing and Sensitive powers plus Levitation, and one Physical or Super-Psionic power per level. Mind Bleeder powers are never available.', '4 to 5 ft (1.2 to 1.5 m)', '90 to 120 lbs (40.8 to 54 kg)', '300 to 500 Earth years', 'Psyscape, where some 10,000 live; also scouting the Magic Zone and beginning to explore North America', 'The citizens of Psyscape and most champions of good; favorably disposed toward Cyber-Knights, Dog Boys and Psi-Stalkers, though each person is judged on his own merits', NULL, 'R.C.C. with its own skill package (printed as O.C.C. Skills); no O.C.C. NPCs average level 4-10; a player character is a young Yhabbayar starting at level one.', 'Short, thin, big-eared D-bees flung to Rifts Earth by a ley line storm who settled among the people of Psyscape, where they are honored as philosophers and teachers of the Third Eye. Cheerful, curious and fond of puns and harmless pranks, they are called Bubblemakers for shaping soap bubbles with the mind and sealing psionics or spells inside them. They shun cybernetics, and money means little to them.', 'Rifts World Book 12: Psyscape p.130-135'),
('zaayr-crystal-dragon', 'Zaayr Crystal Dragon', 'dragon', 'rifts', 1, 'Any, but a good number are anarchist (28%) or unprincipled (22%)', '{"IQ":"4D6","ME":"1D6+12","MA":"2D6+6","PS":"3D6+6","PP":"2D6+6","PE":"3D6+6","PB":"3D6+6","Spd":"4D6+6"}', NULL, NULL, '1D6x100', 'PEx10', 'MEx5', 'Hatchling figures (the playable stage). Spd is running; flying is double. Supernatural P.S. I.S.P. +2D6+2 per level; hatchling P.P.E. does not grow with experience. Bio-regenerates 3D6 M.D. per minute. ADULT: I.Q. 2D6+12, M.A. 2D6+12, M.E. 2D6+12, P.S. 2D6+26, P.P. 2D6+12, P.E. 3D6+12, P.B. 4D6+12, Spd 2D6x10 running or 2D6x10+60 flying; M.D.C. 1D6x1000 + P.E. x2; P.P.E. 2D4x100; I.S.P. +100; Horror/Awe Factor 17; bio-regenerates 1D4x10 M.D. per minute.', NULL, 10, NULL, 'Hatchling: combat equal to Hand to Hand: Basic plus one melee attack, and no bonuses beyond attribute and skill bonuses. Adult: eight physical or psionic attacks per melee (or four plus one by magic), +3 initiative, +2 strike, +2 parry and dodge, +3 pull punch, +3 roll with impact, +1 on all saving throws. Blinding Glare puts ranged attackers at -5 to strike, and close combatants at -7 to strike and parry and -4 to dodge.', 'Literate in Dragonese and one other language; Basic Math (+20%) and Advanced Math 98%; six skills at first level from any category except Cowboy, Medical, Military, Physical, Piloting and Science.', 'Full-spectrum sight and nightvision 1000 ft (305 m); invisible at will by bending light; Blinding Glare (3 I.S.P., daylight or bright light only, line of sight to 3000 ft); reflects lasers harmlessly and can absorb them (5 I.S.P.); radiates heat up to mega-damage levels (5 I.S.P. and 1 P.P.E.); keen hawk-like vision to two miles; sees the invisible; impervious to lasers; half damage from heat and fire; speaks and understands every language; teleport self 14% +2% per level and dimensional teleport 10% +2% per level; shrinks to about 3 ft; metamorphosis into a glossy white-skinned humanoid, one hour per level; flight.', 'Limited to light (not fire) and darkness spells plus Invisibility (Simple and Superior), Close Rift and Dimensional Portal.', 'Master psychic: Astral Golem, Empathic Transmission and Hypnotic Suggestion, plus either all Sensitive or all Healing powers; one power from the other category each level, and one Super-Psionic power every three levels.', 'Hatchling 70% of adult size; adult 15 to 20 ft (4.6 to 6 m) tall and up to 50 ft (15.2 m) long, wingspan about 40-50 ft (12.2 to 15.2 m)', 'Adult 18 tons', '6000 years', 'An alien dimension; hiding in the Astral Plane, with about 230 (60% hatchlings) living in Psyscape and a hundred said to be on the Palladium World', 'Psyscapers and champions of light', 'The Splugorth above all, Necromancers and evil beings (other dragons included) who hunt them for their crystal hides; they loathe Bio-Wizardry and Rune Magic practitioners and all slavers', 'Hatchling R.C.C.; playable only as a first-level hatchling under the usual dragon-hatchling rules (Rifts RPG p.97).', 'Dragons that seem made of living crystal and magical energy, with crystal wings, teeth and claws and eyes of blue energy; perhaps a thousand survive across the Megaverse. Their hide is a priceless universal magic component, so the Splugorth have hunted them almost to extinction, and every Zaayr inherits a racial hatred of the Splugorth and of slavers. Masters of light, they blind, turn invisible, fire lasers from their eyes and breathe magical blue flame.', 'Rifts World Book 12: Psyscape p.135-138'),
('zenith-moon-warper', 'Zenith Moon Warper', 'humanoid', 'rifts', 1, 'Any, although most lean toward anarchist (40%) and evil (30%)', '{"IQ":"1D6+10","ME":"1D6+12","MA":"1D6+2","PS":"2D6+12","PP":"2D6+12","PE":"2D6+12","PB":"3D6+8","Spd":"6D6+20"}', 'PE+5D6', '6D6', 'PE+6D6+12', '2D4x10+PEx2', '1D4x10+MEx3', 'On Rifts Earth a mega-damage being with supernatural P.S. and P.E.: M.D.C. P.E. +6D6+12, +1D6 per level. Hit Points (P.E. +5D6, +1D6 per level) and S.D.C. 6D6 apply on its native world and other low-magic places. I.S.P. and P.P.E. each +1D6+1 per level. When the moon is full or nearly full (about six days a month) P.S., M.D.C. and I.S.P. rise by 20%. Bio-regenerates 3D6 M.D.C. an hour.', NULL, 10, NULL, 'Horror/Awe Factor 10, +1 at levels 4, 8 and 12. Hand to Hand: Expert (cannot be changed); no racial combat bonuses, attacks per melee or damage printed. Needs a 12 or higher to save vs psionic attack. Full moon only: +2 to save vs poison, drugs, possession and mind control, +2 initiative, +1 strike, +1 attack per melee round, +2 to save vs Horror Factor.', 'Gobbleley and Native Tongue 98%; one more language, typically American (+20%); Escape Artist and Pick Pockets (+15% each); Palming, Concealment, Cardsharp, Streetwise and Intelligence (+10% each); Seduction (+20%); Land Navigation (printed as 10%); Wilderness Survival (+5%); W.P. one Ancient, one Energy Weapon and one of choice; Hand to Hand: Expert. Six related skills plus two at levels 3, 5, 8 and 11; four secondary skills.', 'Shape changes into a fully human form at will, but is forced back to its natural canine-headed form for 1D4 hours when the moon reaches its zenith; ambidextrous and double-jointed; nightvision 1000 ft (305 m); swim 60%, climb 80%/70%; leaps 10 ft (3 m) up or forward, half again as far after a run-up; bio-regenerates 3D6 M.D.C. an hour.', 'Innate: Swap Places, Teleport: Lesser (objects), Escape and Tongues, each at half the spell''s normal P.P.E.', 'Major psychic: Psychic Invisibility, Deaden Pain, Induce Sleep and Empathy, plus two powers of choice from Healing, Physical or Sensitive.', '5 to 6 ft (1.5 to 1.8 m)', '120 to 150 lbs (54 to 67.5 kg)', '600+ Earth years', 'Mainly the Magic Zone and the northeastern half of North America, especially eastern Canada and the ''Burbs of Free Quebec', 'Other sneaky, like-minded individuals, varying with the character''s alignment', 'Nothing official, but they often run afoul of the law, and Free Quebec lists them among dangerous D-bees marked for extermination', 'R.C.C. with its own skills, related and secondary skills; takes no O.C.C. NPCs average level 1D4+3; a player character begins at first level.', 'Sleek, attractive canine-headed humanoids often mistaken for werewolves or Dog Boys, also called Zenith Wolves or the Midnight People. They can pass as human except when the moon at its zenith forces their true shape, and they grow stronger around the full moon. Cunning predators and manipulators, they make natural con artists, thieves, spies and assassins, and avoid cybernetics entirely.', 'Rifts World Book 12: Psyscape p.138-140');
INSERT INTO notable_npcs (slug, name, real_name, title, system, race, occ, level, alignment, age, height, weight, attributes, hp, sdc, mdc, ppe, isp, ar, horror_factor, combat, bonuses_note, skills, skills_note, natural_abilities, magic, psionics, super_powers, cybernetics, weapons_and_equipment, money, disposition, allies, enemies, description, source_book) VALUES
('nxla', 'Nxla, the Harvester of Souls', NULL, 'The Harvester of Souls; also called the Cold and the Darkness and the Soul Stealer', 'rifts', 'Alien Intelligence', NULL, NULL, 'Diabolic', NULL, 'About 800 feet (244 m); the size of a 200 story building', 'Incalculable', '{"IQ":25,"ME":30,"MA":14,"PS":60,"PP":24,"PE":26,"PB":1,"Spd":22}', NULL, NULL, 113000, 21000, NULL, NULL, 19, '{"initiative":2,"strike":4,"pull":4}', 'The stored M.D.C. and P.P.E. are the fixed base: the souls inside him add a further 1D4x100,000 M.D.C. and 2D4x10,000 P.P.E. He gains 1000 M.D.C. and 1000 P.P.E. for every 10 million souls taken (p.21). Attacks: 10 physical per 200 foot section of his body, or 10 psionic in total, or two by magic. +2 on all saving throws; impervious to Horror Factor. Attributes are supernatural; damage is as supernatural P.S. 60 (no table printed). M.D. fire, energy weapons, explosives, rail guns and body-affecting magic do full damage; Millennium Tree weapons triple, holy and rune weapons double; psionic energy attacks do ten times normal damage, and psychics are +2 to save vs his magic and immune to his psionic attacks. No I.S.P. is printed.', '[]', 'No skills are printed.', 'Sees in all directions through hundreds of eyes; nightvision 3000 ft (1830 m); hovers and flies at speed 10 up to 1000 ft (305 m); bio-regenerates 1D6x10 M.D.C. per melee round and regrows lost limbs in 24 hours; sees the invisible and turns invisible at will; impervious to poison, radiation, disease, mind control, possession, illusions and normal cold and heat; needs no air and survives vacuum. Can animate and control 1D6x100 dead, turn 1D6x100 dead, summon 6D6 lesser or 2D6 greater demons and cast resurrection. Harvests souls: through a portal opened by Harvesters (900 P.P.E., at most once per 15 days) he enters for 1D6+2 minutes and sends 1D4x10 essence fragments whose victims must save vs possession (15 or higher) or become Soulless Xombies. Once bodily on a world he sends 1000 fragments a day (10,000 after 100 million souls). Directly commands 10,000 Xombies at a time.', 'All Necromancy magic, and spell magic of levels 1-6.', 'All sensitive powers plus Empathic Transmission, Bio-Manipulation and Mentally Possess Others.', NULL, NULL, NULL, NULL, 'A patient, parasitic devourer that recruits death-worshipping fools with promises of power and immortality, then feasts on the souls of whole worlds, savoring captives for ages.', 'Harvesters, other Necromancers, Death Worshippers, lesser demons and enslaved minions; the Soulless Xombies', 'Every intelligent being that wants to keep its soul; on Rifts Earth first of all the heroes of Psyscape, plus all champions of good, the gods of light, and psychics', 'An ancient alien intelligence feared even by the Splugorth, rumored (perhaps by himself) to be the last of the Old Ones to escape their slumber. He manifests as a living tower about 200 stories tall, studded with hundreds of eyes, six arms 200 ft (61 m) long and a dozen tentacles 500 ft (152 m) long. His Harvester cult is working to bring him bodily to Earth; driving him back once he arrives means killing most of his Harvesters, freeing or killing half his Xombies, or cutting his M.D.C. below 30%, after which he cannot return for a century.', 'Rifts World Book 12: Psyscape p.21-24'),
('lt-col-carol-black', 'Lt. Col. Carol Black', 'Carol Black', 'Lieutenant Colonel, soon to be Brigadier General; founder of Psi-Battalion Alpha and head of the CS Psi-Division', 'rifts', 'Human', '11th level Special Forces Operative (O.C.C. data: Coalition War Campaign, page 86)', 11, 'Scrupulous', '53', '5 ft 11 inches (1.79 m)', '140 lbs (63 kg)', '{"IQ":19,"ME":22,"MA":18,"PS":20,"PP":14,"PE":13,"PB":12,"Spd":13}', 44, 32, NULL, 9, 91, NULL, NULL, '{"attacks":7,"initiative":4,"strike":4,"parry":7,"dodge":7,"pull":5,"roll":4}', 'Attacks: 7 physical or psionic; paired weapons. Damage bonus +5. +1 to save vs magic, +4 vs psionic attack, +2 vs possession, +6 vs Horror Factor. M.E. gives +1 vs psionic attack (the book lists it separately); M.A. 50% trust/intimidate.', '[{"name":"Find Contraband","pct":72},{"name":"Lore: D-Bee","pct":90},{"name":"Lore: Psychic","pct":98},{"name":"Computer Operation","pct":98},{"name":"Pilot: Hovercycle","pct":98},{"name":"Literacy: American","pct":98},{"name":"Mathematics: Basic","pct":98},{"name":"Climbing","pct":98}]', 'Every O.C.C. skill at 98%. Climbing is printed 98/98%. Also Hand to Hand: Martial Arts, Boxing and Running. The I.Q. bonus of +8% is already in every figure. W.P.s: all energy weapons, Heavy, Automatic Rifles, Blunt.', NULL, 'None; lore and personal experience only.', 'Major psychic: Intuitive Combat, Mask I.S.P. & Psionics, Mind Block, Object Read, Sense Evil, See the Invisible, Speed Reading, Telepathy.', NULL, 'Clock calendar.', 'The new "Dead Boy" body armor; vibro-knife, CP-40 Pulse Laser Rifle, C-20 laser pistol, and a 9 mm pistol loaded with silver rounds.', NULL, 'Guarded, sharp, inventive and steadfastly honest and loyal; zealous about shielding humanity from D-bees, monsters, magic and renegade psychics. A gifted organizer and administrator with a sound grasp of strategy and tactics, adored by her soldiers.', 'Joseph Prosek II.', NULL, 'The Coalition officer who created Psi-Battalion Alpha and now commands the enlarged Psi-Division. Her push for equal standing for psychics in the military, and for research into psionics as a weapon, has won over the High Command and Joseph Prosek II and is remaking the CS armed forces.', 'Rifts World Book 12: Psyscape p.147');
