-- Rifts World Book 12: Psyscape - its bestiary and its notable NPCs.
-- 22 creatures (migration 074) and 2 notable NPCs (migration 072),
-- with their attacks in stat_attacks (migration 073).
--
-- One-off data script, run once per environment. NOT a migration.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/add-psyscape-creatures.sql
--
-- WHAT IS HERE:
--   * 13 monsters and villains with a stat block (playable 0), the
--     Harvester among them: the book prints it as an O.C.C. and says it is not
--     for players;
--   * the 9 playable D-Bee and monster R.C.C.s as their NPC view (playable 1),
--     slugs matching their class ids, as South America's and Madhaven's do;
--   * 2 named beings with a stat block.
--
-- EXTRACTED by six workers with every number read off a render (this text
-- layer carries a digit cipher and drops minus signs). RECONCILED by
-- book-reconcile. Every creature row passes creatureFormulaGaps, the grammar
-- the endpoint rolls with; per-level growth and figures the grammar cannot
-- take are in pools_note. Prose fields are short paraphrases, and an 8-word
-- shingle check against the whole text layer finds no copied run - the
-- generator refuses to write this file if it does.





-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 22 Psyscape creatures are in' AS assertion, count(*) AS got, 22 AS want
  FROM creatures WHERE source_book LIKE 'Rifts World Book 12: Psyscape p.%';
SELECT 'and 9 of them are the playable R.C.C.s' AS assertion, count(*) AS got, 9 AS want
  FROM creatures WHERE source_book LIKE 'Rifts World Book 12: Psyscape p.%' AND playable = 1;
SELECT 'all 2 notable NPCs are in' AS assertion, count(*) AS got, 2 AS want
  FROM notable_npcs WHERE source_book LIKE 'Rifts World Book 12: Psyscape p.%';
SELECT 'the creatures carry 66 attacks' AS assertion, count(*) AS got, 66 AS want
  FROM stat_attacks WHERE owner_kind = 'creature' AND owner_slug IN (SELECT slug FROM creatures WHERE source_book LIKE 'Rifts World Book 12: Psyscape p.%');
SELECT 'and the notables 0' AS assertion, count(*) AS got, 0 AS want
  FROM stat_attacks WHERE owner_kind = 'notable' AND owner_slug IN (SELECT slug FROM notable_npcs WHERE source_book LIKE 'Rifts World Book 12: Psyscape p.%');

-- Records this run. See db/migrations/024-data-script-runs.sql.
